<script lang="ts">
 type Work={id:number;title:string;category:string;description:string;icon:string};const categories=['ALL','DESIGN','ILLUSTRATION','MUSIC','OTHER'];const works:Work[]=[{id:1,title:'作品情報を準備中',category:'DESIGN',description:'公開可能な作品情報を登録すると詳細を表示します。画面確認用の仮データです。',icon:'◇'},{id:2,title:'作品情報を準備中',category:'ILLUSTRATION',description:'公開可能な作品情報を登録すると詳細を表示します。画面確認用の仮データです。',icon:'✳'},{id:3,title:'作品情報を準備中',category:'MUSIC',description:'公開可能な作品情報を登録すると詳細を表示します。画面確認用の仮データです。',icon:'♫'}];let active=$state('ALL');let selected=$state<Work|null>(null);let visible=$derived(active==='ALL'?works:works.filter(w=>w.category===active));function onKeydown(e:KeyboardEvent){if(e.key==='Escape')selected=null}
</script>
<svelte:head><title>PORTFOLIO — LOCAMinasE</title></svelte:head><svelte:window onkeydown={onKeydown}/><section class="window section"><div class="window-bar"><span>◆ PORTFOLIO / INDEX.DAT</span><b>— □ ×</b></div><div class="content"><p class="kicker">SELECT CATEGORY / OPEN A FILE</p><h1>PORT<br/>FOLIO<span class="accent">.</span></h1><p class="lead">カテゴリを選び、カードを押すと同じ画面に詳細ウィンドウが開きます。</p><div class="filters" aria-label="作品カテゴリ">{#each categories as category}<button class:active={active===category} aria-pressed={active===category} onclick={()=>active=category}>{category}</button>{/each}</div><div class="cards">{#each visible as work (work.id)}<button class="work-card" onclick={()=>selected=work}><div class="art">{work.icon}</div><div class="work-meta"><span>{work.category} / 未設定</span><h3>{work.title}</h3><span>OPEN FILE ↗</span></div></button>{/each}</div><p class="note">掲載内容は画面確認用の仮データです。実作品ではありません。</p></div></section>{#if selected}<div class="modal-backdrop" role="presentation" onclick={(e)=>{if(e.target===e.currentTarget)selected=null}}><dialog open class="modal window" aria-labelledby="work-title"><div class="window-bar"><span>◆ FILE VIEWER / {selected.category}</span><button class="modal-close" aria-label="閉じる" onclick={()=>selected=null}>×</button></div><div class="art">{selected.icon}</div><div class="modal-body"><p class="kicker">{selected.category}</p><h2 id="work-title">{selected.title}</h2><p>{selected.description}</p><button class="button" onclick={()=>selected=null}>CLOSE WINDOW</button></div></dialog></div>{/if}


